export type AuthoritySpec = {
    readonly kind: "file";
    readonly rootDir: string;
} | {
    readonly kind: "database";
    readonly adapter: DatabaseAuthorityAdapter;
};

export type BatchItem<T> = {
    readonly inputIndex: number;
    readonly ok: true;
    readonly value: T;
} | {
    readonly inputIndex: number;
    readonly ok: false;
    readonly error: ErrorShape;
};

interface BatchResult<T> {
  readonly results: readonly BatchItem<T>[];
  readonly meta: ResultMeta;
}

class BoundProviderGraph {
  getProvider(query?: { requiredStaticRevision?: string; }): Promise<ProviderResult>;
  listSpecificationDocuments(query?: DocumentPageQuery): Promise<SpecificationDocumentsPage>;
  listCatalog(query?: Omit<CatalogQuery, "requestProviderScope">): Promise<CatalogPage>;
  getCapabilities(ids: readonly string[], query?: CapabilityDetailQuery): Promise<BatchResult<CapabilityDetail>>;
  listKnowledgeMembers(query: Omit<KnowledgeMembersQuery, "capability"> & { readonly capabilityId: string; }): Promise<KnowledgeMembersPage>;
  getNeighbors(capabilityId: string, query?: NeighborQuery): Promise<NeighborPage>;
  resolveSelection(query: { readonly selected: readonly string[]; readonly requiredStaticRevision?: string; }): Promise<SelectionResult>;
  readDocuments(query: Omit<ReadDocumentsQuery, "requestProviderScope" | "selected"> & { readonly selected: readonly string[]; }): Promise<DocumentReadBatch>;
  readSpecification(query?: Omit<ReadSpecificationQuery, "providerId">): Promise<SpecificationReadBatch>;
  retrieveCapabilities(query: Omit<RetrieveCapabilitiesQuery, "requestProviderScope">): Promise<RetrieveCapabilitiesPage>;
  queryKnowledge(query: Omit<QueryKnowledgeQuery, "requestProviderScope">): Promise<QueryKnowledgePage>;
  queryRuntime(query: Omit<QueryRuntimeQuery, "requestProviderScope">): Promise<QueryRuntimePage>;
}

interface BudgetConfig {
  readonly catalog: { readonly maxBytes: number; readonly maxItems: number; readonly maxItemBytes: number; };
  readonly neighbors: { readonly defaultPageSize: number; readonly maxPageSize: number; readonly maxBytes: number; readonly maxItemBytes: number; };
  readonly detail: { readonly maxCapabilities: number; readonly maxItemBytes: number; readonly maxBytes: number; readonly defaultKnowledgePageSize: number; readonly maxKnowledgePageSize: number; };
  readonly specification: { readonly defaultPageSize: number; readonly maxPageSize: number; readonly maxBytes: number; readonly maxItemBytes: number; };
  readonly selection: { readonly maxSelected: number; readonly maxNodes: number; readonly maxEdges: number; };
  readonly read: { readonly maxBytes: number; readonly maxDocumentsPerCall: number; };
  readonly retrieveCapabilities: { readonly maxCandidates: number; readonly maxCandidateBytes: number; };
  readonly queryKnowledge: { readonly maxHits: number; readonly maxSnippetBytes: number; readonly maxSelected: number; readonly maxFilterValuesPerDimension: number; readonly maxTargets: number; readonly maxTargetBytes: number; };
  readonly runtime: { readonly defaultPageSize: number; readonly maxPageSize: number; readonly timeoutMs: number; readonly maxFactsBytes: number; readonly maxAssociationBytes: number; };
}

export type BudgetOverrides = {
    readonly [K in keyof BudgetConfig]?: Partial<BudgetConfig[K]>;
};

interface CanonicalCapabilityId {
  readonly providerId: string;
  readonly capabilityId: string;
}

interface CapabilityCandidate {
  readonly id: CanonicalCapabilityId;
  readonly qualifiedId: string;
  readonly score?: number;
  readonly rank: number;
}

interface CapabilityDetail {
  readonly qualifiedId: string;
  readonly knowledge: { readonly items: readonly KnowledgeSummary[]; readonly completeness: "complete" | "truncated"; readonly nextCursor?: string; };
  readonly neighborSummaries: Readonly<Record<NeighborKind, NeighborSummaryGroup>>;
  readonly id: CanonicalCapabilityId;
  readonly name: string;
  readonly description: string;
  readonly whenToUse: string;
  readonly distinction?: string;
  readonly staticRevision: string;
  readonly examples: readonly string[];
}

interface CapabilityDetailQuery {
  readonly requiredStaticRevision?: string;
  readonly neighborLimitPerKind?: number;
  readonly knowledgeLimit?: number;
  readonly knowledgeCursors?: Readonly<Record<string, string>>;
}

class CapabilityGraph {
  static open(config: OpenConfig): Promise<CapabilityGraph>;
  reload(options?: { providerId?: string; }): Promise<ReloadResult>;
  close(): Promise<void>;
  forProvider(providerId: string): BoundProviderGraph;
  listProviders(query?: ProviderListQuery): Promise<{ items: ProviderSummary[]; meta: ResultMeta; }>;
  getProvider(providerId: string, query?: { requiredStaticRevision?: string; }): Promise<ProviderResult>;
  listSpecificationDocuments(query: DocumentPageQuery & { readonly providerId: string; }): Promise<SpecificationDocumentsPage>;
  listCatalog(query?: CatalogQuery): Promise<CatalogPage>;
  getCapabilities(ids: readonly CapabilityRef[], query?: CapabilityDetailQuery): Promise<BatchResult<CapabilityDetail>>;
  listKnowledgeMembers(query: KnowledgeMembersQuery): Promise<KnowledgeMembersPage>;
  getNeighbors(ref: CapabilityRef, query?: NeighborQuery): Promise<NeighborPage>;
  resolveSelection(query: ResolveSelectionQuery): Promise<SelectionResult>;
  readDocuments(query: ReadDocumentsQuery): Promise<DocumentReadBatch>;
  readSpecification(query: ReadSpecificationQuery): Promise<SpecificationReadBatch>;
  retrieveCapabilities(query: RetrieveCapabilitiesQuery): Promise<RetrieveCapabilitiesPage>;
  queryKnowledge(query: QueryKnowledgeQuery): Promise<QueryKnowledgePage>;
  queryRuntime(query: QueryRuntimeQuery): Promise<QueryRuntimePage>;
}

class CapabilityGraphError {
  constructor(code: ErrorCode, init: {
    nextAction: NextAction;
    message?: string;
    details?: Record<string, unknown>;
});
}

